static z_t3855_t z_t106_split(
    const z_t106_t* self, const z_t106_t* sep);
static z_t3855_t z_t106_split(
    const z_t106_t* self, const z_t106_t* sep) {
    z_t3855_t s;
    s.src = self->data;
    s.src_len = self->length;
    s.sep = sep->data;
    s.sep_len = sep->length;
    s.cursor = 0;
    s.done = (sep->length == 0);
    return s;
}


static z_t800_t z_t3855_call(z_t3855_t* s);
static z_t800_t z_t3855_call(z_t3855_t* s) {
    z_t800_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    if (s->sep_len > remaining) {
        /* no more separators possible — return the tail */
        z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
        boxed->data = start;
        boxed->length = remaining;
        s->cursor = s->src_len;
        s->done = true;
        out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
        out.data = boxed;
        return out;
    }
    uint64_t scan_end = remaining - s->sep_len;
    for (uint64_t i = 0; i <= scan_end; i++) {
        if (memcmp(start + i, s->sep, s->sep_len) == 0) {
            z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
            boxed->data = start;
            boxed->length = i;
            s->cursor += i + s->sep_len;
            out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
            out.data = boxed;
            return out;
        }
    }
    /* no separator in remaining — final fragment */
    z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
    boxed->data = start;
    boxed->length = remaining;
    s->cursor = s->src_len;
    s->done = true;
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


